50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	const BLOCK_SIZE = 3;
64	
65	const BLOCK_BASE_PREMIUM = 60;
66	
67	const countByType = (items: Item[]): Map<string, number> => {
68	  const counts = new Map<string, number>();
69	
70	  for (const item of items) {
71	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
72	  }
73	
74	  return counts;
75	};
76	
77	const typeGroupBasePremiumOf = ([type, count]: [string, number]): number =>
78	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
79	
80	const policyBasePremiumOf = (items: Item[]): number =>
81	  [...countByType(items)].reduce(
82	    (sum, typeGroup) => sum + typeGroupBasePremiumOf(typeGroup),
83	    0,
84	  );
85	
86	const CURSE_SURCHARGE_RATE = 0.5;
87	
88	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
89	
90	const HIGH_ENCHANTMENT_THRESHOLD = 5;
91	
92	const isCursed = (item: Item): boolean => item.cursed === true;
93	
94	const isHighlyEnchanted = (item: Item): boolean =>
95	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
96	
97	const surchargeOf = (
98	  items: Item[],
99	  applies: (item: Item) => boolean,
100	  rate: number,
101	): number =>
102	  items
103	    .filter(applies)
104	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * rate, 0);
105	
106	// Item-specific modifiers apply to the affected item's own base premium.
107	const itemModifiersOf = (items: Item[]): number =>
108	  surchargeOf(items, isCursed, CURSE_SURCHARGE_RATE) +
109	  surchargeOf(items, isHighlyEnchanted, HIGH_ENCHANTMENT_SURCHARGE_RATE);
110	
111	// Policy-wide modifiers apply to the policy base premium, so they are computed
112	// from the base alone — item-specific modifiers are not part of their base.
113	const policyModifiersOf = (policyBase: number): number =>
114	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
115	
116	const quote = ({ items }: QuoteStep): QuoteResult => {
117	  const policyBase = policyBasePremiumOf(items);
118	
119	  const premiumBeforeRounding =
120	    policyBase + itemModifiersOf(items) + policyModifiersOf(policyBase) + PROCESSING_FEE;
121	
122	  return { premium: Math.ceil(premiumBeforeRounding) };
123	};
124	
125	const runStep = (step: Step): StepResult => {
126	  if (step.op === "quote") return quote(step);
127	
128	  throw new Error(`unsupported step: ${step.op}`);
129	};
130	
131	export const runScenario = (scenario: Scenario): ScenarioResult => ({
132	  results: scenario.steps.map(runStep),
133	});
