const HIGH_ENCHANTMENT_THRESHOLD = 5;

// An item surcharge hits every item the predicate accepts, charging its rate
// against that item's own base premium.
interface ItemSurcharge {
  appliesTo: (item: Item) => boolean;
  rate: number;
}

const ITEM_SURCHARGES: ItemSurcharge[] = [
  { appliesTo: (item) => item.cursed === true, rate: 0.5 },
  {
    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
    rate: 0.3,
  },
];

const surchargeOf = (items: Item[], { appliesTo, rate }: ItemSurcharge): number =>
  items
    .filter(appliesTo)
    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * rate, 0);

// Item-specific modifiers apply to the affected item's own base premium.
const itemModifiersOf = (items: Item[]): number =>
  ITEM_SURCHARGES.reduce(
    (sum, surcharge) => sum + surchargeOf(items, surcharge),
    0,
  );
